// simplified acceptor state machine, not production code
class Acceptor {
  promisedNum = 0;
  acceptedNum = 0;
  acceptedValue = null;

  onPrepare(num) {
    if (num > this.promisedNum) {
      this.promisedNum = num;
      return { promised: true, acceptedNum: this.acceptedNum, acceptedValue: this.acceptedValue };
    }
    return { promised: false };
  }

  onAccept(num, value) {
    if (num >= this.promisedNum) {
      this.promisedNum = num;
      this.acceptedNum = num;
      this.acceptedValue = value;
      return { accepted: true };
    }
    return { accepted: false };
  }
}

