// simplified follower side election logic, not production code
function onElectionTimeout(node) {
  node.currentTerm += 1;
  node.state = 'candidate';
  node.votedFor = node.id;
  let votes = 1; // votes for itself

  for (const peer of node.peers) {
    const granted = requestVote(peer, node.currentTerm, node.lastLogIndex);
    if (granted) votes += 1;
  }

  if (votes > node.peers.length / 2) {
    node.state = 'leader';
    startSendingHeartbeats(node);
  } else {
    resetRandomizedElectionTimeout(node);
  }
}

